"""Tiny synthetic PDFs generated by code, so the repo contains no third-party document.

The "handbook" is entirely fictional. Its facts are used by the tests and by the --mock evaluation.
"""
from __future__ import annotations

from pathlib import Path

from reportlab.lib.pagesizes import A4
from reportlab.pdfgen import canvas

HANDBOOK_PAGES = [
    [
        "Harbor Lane Studio - Staff Handbook (synthetic example)",
        "Remote work: employees may work remotely up to 3 days per week with manager approval.",
        "Core hours are 10:00 to 15:00 local time, when everyone must be reachable.",
        "Equipment: the company provides a laptop and a monitor.",
        "A home-office stipend of 400 dollars is paid once every 2 years.",
    ],
    [
        "Leave policy",
        "Annual leave is 22 days per year.",
        "Up to 5 unused days of annual leave carry over into the next year.",
        "Sick leave is 10 days per year.",
        "A medical certificate is required after 3 consecutive sick days.",
    ],
    [
        "Security and expenses",
        "Passwords must be at least 14 characters long.",
        "Laptops use full-disk encryption.",
        "A lost device must be reported within 24 hours.",
        "Expense claims must be submitted within 30 days, with receipts.",
        "Meals are capped at 40 dollars per day when travelling.",
    ],
]


def make_handbook_pdf(path: Path | str) -> Path:
    """Write the 3-page fictional handbook (text layer included)."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    c = canvas.Canvas(str(path), pagesize=A4)
    for lines in HANDBOOK_PAGES:
        y = 800
        for line in lines:
            c.drawString(50, y, line)
            y -= 24
        c.showPage()
    c.save()
    return path


def make_image_only_pdf(path: Path | str) -> Path:
    """A PDF whose pages draw only shapes: no text layer, like a scan."""
    path = Path(path)
    c = canvas.Canvas(str(path), pagesize=A4)
    c.rect(50, 50, 300, 200, fill=1)
    c.showPage()
    c.save()
    return path


if __name__ == "__main__":
    print(make_handbook_pdf(Path("data/sample/synthetic_handbook.pdf")))
